package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ChangeSchedulingAcceptance {
 static String api(String id){return "/api/openservice/change_request/"+id+"/schedule";}
 static String windows(String ci){return "/api/openservice/change-windows/"+ci;}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r)throws Exception{return ProblemInvestigationsAcceptance.result(r);}
 static Map<String,Object> page(WorkflowSupport h,String id)throws Exception{return result(h.get(api(id),auth("admin")));}
 static Map<String,Object> command(WorkflowSupport h,String id,String op)throws Exception{var p=page(h,id);return map("operation",op,"revision",object(p.get("schedule")).get("revision"),"record_revision",ProblemInvestigationsAcceptance.revision(object(p.get("change"))));}
 static Map<String,Object> proposed(WorkflowSupport h,String id,String ci,String start,String end)throws Exception{var b=command(h,id,"save");b.putAll(map("ci_id",ci,"start",start,"end",end));return b;}
 static Map<String,Object> save(WorkflowSupport h,String id,String ci,String start,String end)throws Exception{return result(h.json("POST",api(id),proposed(h,id,ci,start,end),auth("admin")));}
 static boolean blocked(WorkflowSupport h,String id)throws Exception{return Boolean.TRUE.equals(object(page(h,id).get("findings")).get("blocked"));}
 static String change(WorkflowSupport h)throws Exception{String id=h.add("change_request").get("sys_id").toString();ready(h,id);return id;}
 static void ready(WorkflowSupport h,String id)throws Exception{ChangePlanningAcceptance.save(h,id,ChangePlanningAcceptance.body(h,id,true));}
 static void state(WorkflowSupport h,String id,String state,int status)throws Exception{ChangePlanningAcceptance.patch(h,id,map("state",state),status);}
 static void calendar(WorkflowSupport h,String name,String zone,String start,String end,List<Integer> days,List<String> holidays)throws Exception{try(var db=h.store.open()){String admin=PlatformFoundationTest.bind(db);ServiceClocks.calendar(db,admin,map("name",name,"calendar",map("zone",zone,"start",start,"end",end,"days",days,"holidays",holidays)));db.connection.commit();}}
 static Map<String,Object> window(String name,String kind,String calendar){return map("operation","create","revision",0,"name",name,"kind",kind,"calendar_id",calendar,"active",true);}
 static String addWindow(WorkflowSupport h,String ci,String kind,String calendar)throws Exception{var p=result(h.json("POST",windows(ci),window(kind+" "+calendar,kind,calendar),auth("admin")));return objects(p.get("windows")).stream().filter(w->w.get("calendar_id").equals(calendar)).findFirst().orElseThrow().get("window_id").toString();}
 static Map<String,Object> windowCommand(WorkflowSupport h,String ci,String id,String op)throws Exception{var current=objects(result(h.get(windows(ci),auth("admin"))).get("windows")).stream().filter(w->w.get("window_id").equals(id)).findFirst().orElseThrow();var b=map("operation",op,"window_id",id,"revision",current.get("revision"));if(op.equals("save"))for(String key:List.of("name","kind","calendar_id","active"))b.put(key,key.equals("active")?((Number)current.get(key)).intValue()==1:current.get(key));return b;}
 static void run(WorkflowSupport h)throws Exception{
  String ci=h.add("cmdb_ci").get("sys_id").toString(),a=change(h),b=change(h);calendar(h,"Workday","UTC","08:00","18:00",List.of(1,2,3,4,5),List.of());calendar(h,"Freeze","UTC","10:00","11:00",List.of(1,2,3,4,5),List.of());addWindow(h,ci,"maintenance","Workday");String freeze=addWindow(h,ci,"blackout","Freeze");
  var original=proposed(h,a,ci,"2026-11-18T09:00:00Z","2026-11-18T10:00:00Z");result(h.json("POST",api(a),original,auth("admin")));assertEquals(409,h.json("POST",api(a),original,auth("admin")).statusCode());assertFalse(blocked(h,a));assertEquals(false,ChangePlanningAcceptance.get(h,a).get("current"));state(h,a,"review",409);ready(h,a);
  save(h,b,ci,"2026-11-18T09:30:00Z","2026-11-18T10:30:00Z");assertTrue(blocked(h,a));assertTrue(blocked(h,b));assertEquals(1,objects(object(page(h,b).get("findings")).get("changes")).size());assertTrue(object(page(h,b).get("findings")).get("windows").toString().contains("Blackout"));ready(h,b);state(h,b,"review",409);
  save(h,b,ci,"2026-11-18T11:00:00Z","2026-11-18T12:00:00Z");ready(h,b);assertFalse(blocked(h,a));for(String state:List.of("review","approved","implement","closed"))state(h,a,state,200);assertEquals(409,h.json("POST",api(a),command(h,a,"clear"),auth("admin")).statusCode());assertFalse(blocked(h,b));
  calendar(h,"Freeze","UTC","11:00","12:00",List.of(1,2,3,4,5),List.of());assertTrue(blocked(h,b));state(h,b,"review",409);var disable=windowCommand(h,ci,freeze,"save");disable.put("active",false);result(h.json("POST",windows(ci),disable,auth("admin")));state(h,b,"review",200);state(h,b,"approved",200);disable=windowCommand(h,ci,freeze,"save");disable.put("active",true);result(h.json("POST",windows(ci),disable,auth("admin")));state(h,b,"implement",409);state(h,b,"rejected",200);assertEquals(0,objects(object(page(h,a).get("findings")).get("changes")).size());result(h.json("POST",api(b),command(h,b,"clear"),auth("admin")));assertEquals(0,object(page(h,b).get("schedule")).get("revision"));ready(h,b);state(h,b,"draft",200);
  assertEquals(409,h.json("DELETE","/api/now/table/cmdb_ci/"+ci,map(),auth("admin")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/change_request/"+a,map(),auth("admin")).statusCode());new Store(h.environment);assertEquals(2,objects(result(h.get(windows(ci),auth("admin"))).get("windows")).size());assertEquals(204,h.json("DELETE","/api/now/table/cmdb_ci/"+ci,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_change_window"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_change_schedule"));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  String ci=h.add("cmdb_ci").get("sys_id").toString(),id=h.add("change_request").get("sys_id").toString();h.account("ScheduleReader","reader");h.account("ScheduleAgent","agent");assertEquals(403,h.get(api(id),auth("ScheduleReader")).statusCode());assertEquals(403,h.get(windows(ci),auth("ScheduleAgent")).statusCode());assertEquals(404,h.get(windows("f".repeat(32)),auth("admin")).statusCode());assertEquals(405,h.json("PUT",api(id),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(id)+"?extra=x",auth("admin")).statusCode());assertEquals(400,h.get(windows(ci)+"?extra=x",auth("admin")).statusCode());assertEquals(409,h.json("POST",api(id),proposed(h,id,ci,"2026-11-18T09:00:00Z","2026-11-18T10:00:00Z"),auth("admin")).statusCode());ready(h,id);
  for(var pair:List.of(List.of("bad","2026-11-18T10:00:00Z"),List.of("2026-11-18T09:00:00.001Z","2026-11-18T10:00:00Z"),List.of("1969-12-31T23:59:59Z","2026-11-18T10:00:00Z"),List.of("2101-01-01T00:00:00Z","2101-01-02T00:00:00Z"),List.of("+999999999-01-01T00:00:00Z","2026-11-18T10:00:00Z"),List.of("2026-11-18T10:00:00Z","2026-11-18T09:00:00Z"),List.of("2026-11-18T10:00:00Z","2026-12-20T10:00:00Z"))){assertEquals(400,h.json("POST",api(id),proposed(h,id,ci,pair.get(0),pair.get(1)),auth("admin")).statusCode());}
  for(var bad:List.of(map("operation","other"),map("operation","save","revision",0,"record_revision",1))){assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());}assertEquals(404,h.json("POST",api(id),proposed(h,id,"f".repeat(32),"2026-11-18T09:00:00Z","2026-11-18T10:00:00Z"),auth("admin")).statusCode());save(h,id,ci,"1970-01-01T00:00:00Z","1970-01-02T00:00:00Z");assertEquals("1970-01-01T00:00:00Z",page(h,id).get("start"));ready(h,id);assertEquals(true,ChangePlanningAcceptance.get(h,id).get("current"));
  calendar(h,"Daily","UTC","08:00","18:00",List.of(1,2,3,4,5,6,7),List.of());var valid=window("Window","maintenance","Daily");for(var change:List.of(map("kind","unknown"),map("calendar_id","missing"),map("active","true"),map("name",""),map("revision",1),map("extra",1))){var bad=new LinkedHashMap<>(valid);bad.putAll(change);assertEquals(change.containsKey("revision")?409:400,h.json("POST",windows(ci),bad,auth("admin")).statusCode());}assertEquals(400,h.json("POST",windows(ci),map("operation","other"),auth("admin")).statusCode());assertEquals(404,h.json("POST",windows(ci),map("operation","remove","revision",0,"window_id","f".repeat(32)),auth("admin")).statusCode());String window=addWindow(h,ci,"maintenance","Daily");var stale=windowCommand(h,ci,window,"save");result(h.json("POST",windows(ci),stale,auth("admin")));assertEquals(409,h.json("POST",windows(ci),stale,auth("admin")).statusCode());String other=h.add("cmdb_ci").get("sys_id").toString();assertEquals(404,h.json("POST",windows(other),windowCommand(h,ci,window,"remove"),auth("admin")).statusCode());result(h.json("POST",windows(ci),windowCommand(h,ci,window,"remove"),auth("admin")));assertTrue(objects(result(h.get(windows(ci),auth("admin"))).get("windows")).isEmpty());
  for(int n=0;n<20;n++)result(h.json("POST",windows(ci),window("Limit "+n,"blackout","Daily"),auth("admin")));assertEquals(400,h.json("POST",windows(ci),valid,auth("admin")).statusCode());var form=new LinkedHashMap<>(valid);form.remove("active");assertEquals(400,h.protectedForm("/admin/change-windows/"+ci,form,auth("admin")).statusCode());assertEquals(403,h.form("/admin/change-windows/"+ci,valid,auth("admin")).statusCode());assertEquals(400,h.protectedForm("/record/change_request/"+id+"/schedule",map("operation","clear","revision","bad","record_revision",1),auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception{
  h.account("ScheduleWorker","agent");String ci=h.add("cmdb_ci").get("sys_id").toString(),a=change(h),b=change(h);save(h,a,ci,"2026-11-18T09:00:00Z","2026-11-18T10:00:00Z");save(h,b,ci,"2026-11-18T09:30:00Z","2026-11-18T10:30:00Z");String admin;try(var db=h.store.open()){admin=RecordAccess.owner(db,"admin");}ProblemInvestigationsAcceptance.access(h,"change_request",a,"private",admin);var shown=result(h.get(api(b),auth("ScheduleWorker")));assertEquals(true,object(shown.get("findings")).get("restricted"));assertFalse(shown.toString().contains(a));assertTrue(objects(object(shown.get("findings")).get("changes")).isEmpty());ready(h,b);state(h,b,"review",409);Map<String,Object> original,ciSchema;try(var db=h.store.open()){original=Service.schema(db,"change_request");ciSchema=Service.schema(db,"cmdb_ci");}
  var denied=new LinkedHashMap<>(original);denied.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"change_request",denied);try{var before=object(page(h,b).get("schedule"));assertEquals(403,h.json("POST",api(b),command(h,b,"clear"),auth("ScheduleWorker")).statusCode());assertEquals(before,object(page(h,b).get("schedule")));}finally{ReferencePickerAcceptance.writeSchema(h,"change_request",original);}
  ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ci,"private",admin);shown=result(h.get(api(b),auth("ScheduleWorker")));assertEquals("",object(shown.get("schedule")).get("ci_id"));assertNull(shown.get("selected"));assertEquals(true,object(shown.get("findings")).get("blocked"));assertFalse(shown.toString().contains(ci));result(h.json("POST",api(b),command(h,b,"clear"),auth("ScheduleWorker")));ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ci,"workspace","");
  var hidden=new LinkedHashMap<>(ciSchema);hidden.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",hidden);try{assertTrue(objects(object(result(h.get(api(b),auth("ScheduleWorker"))).get("search")).get("items")).isEmpty());assertEquals(400,h.get(api(b)+"?extra=x",auth("ScheduleWorker")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",ciSchema);}
  save(h,b,ci,"2026-11-18T10:00:00Z","2026-11-18T11:00:00Z");assertFalse(blocked(h,b));ready(h,b);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,"change_request",b);db.update("UPDATE os_change_schedule SET starts=?,ends=? WHERE change_id=?",ChangeScheduling.instant("2026-11-18T09:30:00Z"),ChangeScheduling.instant("2026-11-18T10:30:00Z"),b);var plan=ChangePlanning.plan(db,b);var detail=object(plan.get("detail"));detail.put("snapshot",ChangePlanning.snapshot(db,item));db.update("UPDATE os_change_plan SET detail=? WHERE change_id=?",JSON.writeValueAsString(detail),b);object(item.get("data")).put("state","review");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,item)).status);db.connection.rollback();}
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=0;n<51;n++){String peer=Service.create(db,"change_request",map("short_description","Overlapping reservation "+n),"admin").get("sys_id").toString();db.update("INSERT INTO os_change_schedule(change_id,ci_id,starts,ends,revision) VALUES(?,?,?,?,1)",peer,ci,ChangeScheduling.instant("2026-11-18T10:00:00Z"),ChangeScheduling.instant("2026-11-18T11:00:00Z"));}db.connection.commit();}assertEquals(true,object(page(h,b).get("findings")).get("more"));assertEquals(50,objects(object(page(h,b).get("findings")).get("changes")).size());
 }
 static void calendars(WorkflowSupport h)throws Exception{
  String ci=h.add("cmdb_ci").get("sys_id").toString(),id=change(h);calendar(h,"NewYork","America/New_York","01:00","04:00",List.of(7),List.of());String maintenance=addWindow(h,ci,"maintenance","NewYork");save(h,id,ci,"2026-11-01T05:00:00Z","2026-11-01T09:00:00Z");assertFalse(blocked(h,id));save(h,id,ci,"2026-11-01T05:00:00Z","2026-11-01T09:00:01Z");assertTrue(blocked(h,id));calendar(h,"NewYork","America/New_York","01:00","04:00",List.of(7),List.of("2026-11-01"));assertTrue(blocked(h,id));calendar(h,"Fallback","UTC","00:00","12:00",List.of(7),List.of());addWindow(h,ci,"maintenance","Fallback");assertFalse(blocked(h,id));try(var db=h.store.open()){db.update("DELETE FROM os_calendar WHERE calendar_id='NewYork'");db.connection.commit();}assertTrue(object(page(h,id).get("findings")).get("windows").toString().contains("Unavailable calendar"));assertTrue(blocked(h,id));result(h.json("POST",windows(ci),windowCommand(h,ci,maintenance,"remove"),auth("admin")));assertFalse(blocked(h,id));new Store(h.environment);assertFalse(blocked(h,id));
 }
}
